seed = 4, t = 10000.0, s = 0.001
@pytest.mark.parametrize("seed", (4, 6, 9, 11, 13, 17)) @pytest.mark.parametrize("t,s", [(1e4, 1e-3), (1e5, 1e-3), (1e6, 1e-2)]) def test_touching_near_parallel_edges_crossing_at_an_endpoint_stay_in_extent(seed, t, s): """原端点闭式条件保留；全部舍入运动格按独立精确参数分类，不以噪声窗口改成在程。""" A0, B0 = _corner_pair(1e-5, 0.0) c0,truth0 = _check_ee_exact(A0,(0,1),B0,(4,5)) assert c0 is not None and c0.in_extent and abs(c0.gap) < 1e-12 assert abs(c0.params[0] - 1.0) < 1e-9 and abs(c0.params[1] - 0.8) < 1e-9 tv = (t * 0.6, -t * 0.48, t * 0.64) A, B = _xf(A0, _rot3(seed), tv, s), _xf(B0, _rot3(seed), tv, s) c,truth = _check_ee_exact(A,(0,1),B,(4,5)) > assert c is not None and truth is not None E assert (None is not None)
tests\test_frozen_ee_sign.py:214: AssertionError

